function HeroSection() {
  return (
    <div
      style={{
        textAlign: "center",
        padding: "80px 20px",
        background: "#f5f5f5"
      }}
    >
      <h1 style={{ fontWeight: "bold" }}>
        Discover Events at KU
      </h1>

      <p
        style={{
          marginTop: "15px",
          color: "#555",
          fontSize: "18px"
        }}
      >
        Connect with clubs, explore exciting events, and make unforgettable memories
      </p>
    </div>
  );
}

export default HeroSection;
